import{_ as e,o as s,c as n,a2 as t}from"./chunks/framework.BXzK3EA4.js";const o="/assets/image%20(1)%20(1)%20(1).DrJ4MAId.png",r="/assets/image%20(145).TqLwUehR.png",b=JSON.parse('{"title":"Raspberry Pi","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guidelines/getting-started/raspberry-pi.md","filePath":"installation-guidelines/getting-started/raspberry-pi.md"}'),i={name:"installation-guidelines/getting-started/raspberry-pi.md"};function p(l,a,d,c,u,h){return s(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="raspberry-pi" tabindex="-1">Raspberry Pi <a class="header-anchor" href="#raspberry-pi" aria-label="Permalink to &quot;Raspberry Pi&quot;">​</a></h1><h2 id="tradeboard-on-raspberry-pi-setup-guide" tabindex="-1">Tradeboard on Raspberry Pi: Setup Guide <a class="header-anchor" href="#tradeboard-on-raspberry-pi-setup-guide" aria-label="Permalink to &quot;Tradeboard on Raspberry Pi: Setup Guide&quot;">​</a></h2><p><strong>This guide helps you install and configure Tradeboard on Raspberry Pi models 3, 4, or 5 (4GB+ RAM), preferably running Ubuntu 24.04+ server edition.</strong></p><figure><img src="'+o+'" alt=""><figcaption></figcaption></figure><h3 id="hardware-os-recommendations" tabindex="-1">Hardware &amp; OS Recommendations <a class="header-anchor" href="#hardware-os-recommendations" aria-label="Permalink to &quot;Hardware &amp; OS Recommendations&quot;">​</a></h3><ul><li><strong>Raspberry Pi Model</strong>: 3, 4, or 5 (minimum 4GB RAM)</li><li><strong>SD Card</strong>: Recommended 128GB; minimum 64GB</li><li><strong>Operating System</strong>: Ubuntu 24.04+ Server edition (preferred)</li><li><strong>RPi official power adapter</strong>: Recommended to buy for stable power supply and avoid RPi abrupt shutdowns and restarts. <a href="https://ubuntu.com/download/raspberry-pi" target="_blank" rel="noreferrer">Get Ubuntu images for Raspberry Pi</a></li></ul><figure><img src="'+r+`" alt=""><figcaption></figcaption></figure><h3 id="initial-system-preparation" tabindex="-1">Initial System Preparation <a class="header-anchor" href="#initial-system-preparation" aria-label="Permalink to &quot;Initial System Preparation&quot;">​</a></h3><h4 id="_1-flash-os-to-sd-card" tabindex="-1">1. Flash OS to SD Card <a class="header-anchor" href="#_1-flash-os-to-sd-card" aria-label="Permalink to &quot;1. Flash OS to SD Card&quot;">​</a></h4><ul><li>Use <a href="https://www.raspberrypi.com/software/" target="_blank" rel="noreferrer">Raspberry Pi Imager</a> to prepare your SD card.</li><li>Configure initial user, password, Wi-Fi details, etc.</li></ul><h4 id="_2-first-boot-access" tabindex="-1">2. First Boot &amp; Access <a class="header-anchor" href="#_2-first-boot-access" aria-label="Permalink to &quot;2. First Boot &amp; Access&quot;">​</a></h4><ul><li><p>Insert SD card, power on Raspberry Pi.</p></li><li><p>Connect HDMI to monitor/TV and USB keyboard <strong>or</strong> get the private IP from your router/AP and SSH to RPi instance :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssh &lt;username&gt;@&lt;raspberry-pi-ip&gt;</span></span></code></pre></div></li><li><p><a href="https://www.raspberrypi.com/documentation/computers/getting-started.html" target="_blank" rel="noreferrer">Official Raspberry Pi SSH guide</a></p></li></ul><h4 id="_3-setup-swap" tabindex="-1">3. Setup Swap <a class="header-anchor" href="#_3-setup-swap" aria-label="Permalink to &quot;3. Setup Swap&quot;">​</a></h4><ul><li><p>Recommend swap size: <strong>max 4GB, min 2GB</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo fallocate -l 4G /swapfile</span></span>
<span class="line"><span>sudo chmod 600 /swapfile</span></span>
<span class="line"><span>sudo mkswap /swapfile</span></span>
<span class="line"><span>sudo swapon /swapfile</span></span>
<span class="line"><span>echo &#39;/swapfile none swap sw 0 0&#39; | sudo tee -a /etc/fstab</span></span></code></pre></div></li></ul><h3 id="tradeboard-installation" tabindex="-1">Tradeboard Installation <a class="header-anchor" href="#tradeboard-installation" aria-label="Permalink to &quot;Tradeboard Installation&quot;">​</a></h3><h4 id="option-1-using-official-install-script" tabindex="-1">Option 1: Using Official Install Script <a class="header-anchor" href="#option-1-using-official-install-script" aria-label="Permalink to &quot;Option 1: Using Official Install Script&quot;">​</a></h4><ul><li><strong>Visit</strong>: <a href="https://docs.algo.wesoftcorp.com/installation-guidelines/getting-started" target="_blank" rel="noreferrer">Install Instructions</a></li><li><strong>Follow the script prompts.</strong><br> (Typically involves downloading, running the script, and entering your details.)</li></ul><h4 id="option-2-docker-based-setup-recommended-for-advanced-users" tabindex="-1">Option 2: Docker-Based Setup (Recommended for advanced users) <a class="header-anchor" href="#option-2-docker-based-setup-recommended-for-advanced-users" aria-label="Permalink to &quot;Option 2: Docker-Based Setup (Recommended for advanced users)&quot;">​</a></h4><p><strong>1. Install Docker (Ubuntu/ARM)</strong></p><p><a href="https://docs.docker.com/engine/install/ubuntu/" target="_blank" rel="noreferrer">Docker Ubuntu install guide</a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-get update</span></span>
<span class="line"><span>sudo apt-get install ca-certificates curl gnupg</span></span>
<span class="line"><span>curl -fsSL https://get.docker.com -o get-docker.sh</span></span>
<span class="line"><span>sudo sh get-docker.sh</span></span></code></pre></div><p><strong>2. Install Docker Buildx for ARM</strong></p><p><code>docker buildx version</code></p><p>If not present, follow: <a href="https://docs.docker.com/buildx/working-with-buildx/#install-buildx" target="_blank" rel="noreferrer">https://docs.docker.com/buildx/working-with-buildx/#install-buildx</a></p><p><strong>3. Get nginx Docker Image (reverse proxy)</strong></p><p><code>docker pull nginx:latest</code></p><p><strong>4. Clone the Tradeboard Repo</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/wesoftcorp/tradeboard</span></span>
<span class="line"><span>cd tradeboard</span></span></code></pre></div><p><strong>5. Build Tradeboard Docker Image</strong></p><p><code>docker build -t tradeboard:latest .</code></p><p><strong>6. Configure Environment</strong></p><ul><li><p>Copy <code>.sample.env</code> as <code>.env</code> and fill in <strong>broker API key, secret, and client ID</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cp .sample.env .env</span></span>
<span class="line"><span>vi .env</span></span></code></pre></div></li></ul><p><strong>7. Use docker-compose.yaml</strong></p><ul><li><p>Edit/verify <code>docker-compose.yaml</code> inside <code>/tradeboard</code></p></li><li><p>If you have built the docker image in the previous step, you can comment the <code>build:</code> block and its nested keys (using #) in <code>docker-compose.yaml</code>.</p></li><li><p>Launch services:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker compose up -d</span></span></code></pre></div><p>Use the <code>docker compose</code> subcommand (Compose v2). The standalone <code>docker-compose</code> v1 binary is end of life and is not installed by the <code>get-docker.sh</code> script above.</p></li></ul><p><strong>8. Configure Nginx Reverse Proxy</strong></p><ul><li><p>Reference: <a href="https://github.com/wesoftcorp/tradeboard/blob/main/install/install-multi.sh" target="_blank" rel="noreferrer">Install Multi-Script Example</a></p></li><li><p>Typical location blocks for nginx. Tradeboard publishes <strong>two</strong> ports, so you need both: the Flask app on <code>5000</code> and the WebSocket proxy on <code>8765</code>. Without the <code>/ws</code> block the dashboard loads but live prices never update.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location = /ws {</span></span>
<span class="line"><span>    proxy_pass http://127.0.0.1:8765;</span></span>
<span class="line"><span>    proxy_http_version 1.1;</span></span>
<span class="line"><span>    proxy_set_header Upgrade $http_upgrade;</span></span>
<span class="line"><span>    proxy_set_header Connection &quot;upgrade&quot;;</span></span>
<span class="line"><span>    proxy_set_header Host $host;</span></span>
<span class="line"><span>    proxy_read_timeout 86400s;</span></span>
<span class="line"><span>    proxy_send_timeout 86400s;</span></span>
<span class="line"><span>    proxy_buffering off;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>location /ws/ {</span></span>
<span class="line"><span>    proxy_pass http://127.0.0.1:8765/;</span></span>
<span class="line"><span>    proxy_http_version 1.1;</span></span>
<span class="line"><span>    proxy_set_header Upgrade $http_upgrade;</span></span>
<span class="line"><span>    proxy_set_header Connection &quot;upgrade&quot;;</span></span>
<span class="line"><span>    proxy_set_header Host $host;</span></span>
<span class="line"><span>    proxy_read_timeout 86400s;</span></span>
<span class="line"><span>    proxy_send_timeout 86400s;</span></span>
<span class="line"><span>    proxy_buffering off;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>location /socket.io/ {</span></span>
<span class="line"><span>    proxy_pass http://127.0.0.1:5000/socket.io/;</span></span>
<span class="line"><span>    proxy_http_version 1.1;</span></span>
<span class="line"><span>    proxy_set_header Upgrade $http_upgrade;</span></span>
<span class="line"><span>    proxy_set_header Connection &quot;upgrade&quot;;</span></span>
<span class="line"><span>    proxy_set_header Host $host;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>location / {</span></span>
<span class="line"><span>    proxy_pass http://127.0.0.1:5000;</span></span>
<span class="line"><span>    proxy_set_header Host $host;</span></span>
<span class="line"><span>    proxy_set_header X-Real-IP $remote_addr;</span></span>
<span class="line"><span>    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;</span></span>
<span class="line"><span>    proxy_set_header X-Forwarded-Proto $scheme;</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>Do not add <code>Upgrade</code> / <code>Connection &quot;upgrade&quot;</code> headers to the <code>location / {</code> block. Doing so sends every ordinary request upstream with a bogus upgrade header, which breaks HTTP/1.1 keep-alive to Gunicorn and shows up as intermittent failures. Only the <code>/ws</code>, <code>/ws/</code> and <code>/socket.io/</code> blocks need them.</p></li><li><p>Then set the matching values in <code>.env</code> so the browser is told the right address, and so Tradeboard trusts the forwarded client IP:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">HOST_SERVER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://yourdomain.com&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">WEBSOCKET_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wss://yourdomain.com/ws&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">WEBSOCKET_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0.0.0.0&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TRUST_PROXY_HEADERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;TRUE&#39;</span></span></code></pre></div><p>Leave <code>ZMQ_HOST</code> on <code>127.0.0.1</code>. It is the unauthenticated internal tick bus and must never be reachable off the host.</p></li><li><p>Adapt your domain/server settings accordingly.</p></li></ul><h3 id="persistent-storage-recommended-practice" tabindex="-1">Persistent Storage (Recommended Practice) <a class="header-anchor" href="#persistent-storage-recommended-practice" aria-label="Permalink to &quot;Persistent Storage (Recommended Practice)&quot;">​</a></h3><p>I prefer to separate out the runtime files and folders from the github cloned folder and keep them separate. So if you build the docker image as in above step #5, you can very well take the docker-compose.yaml in a separate working folder structure and have your own versions of .env file.</p><ul><li><p>Create and mount volumes under <code>/work</code> for logs, keys, strategies, etc.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/work</span></span>
<span class="line"><span>  /storage</span></span>
<span class="line"><span>     /tradeboard</span></span>
<span class="line"><span>         docker-compose.yaml</span></span>
<span class="line"><span>         .env</span></span>
<span class="line"><span>         applogs/</span></span>
<span class="line"><span>         logs/</span></span>
<span class="line"><span>         keys/</span></span>
<span class="line"><span>         strategies/</span></span>
<span class="line"><span>         db/</span></span></code></pre></div></li><li><p>Update <code>docker-compose.yaml</code> <a href="https://github.com/wesoftcorp/tradeboard/blob/main/docker-compose.yaml" target="_blank" rel="noreferrer">example</a>. The application lives at <code>/app</code> inside the container, so the container-side path of every bind mount must start with <code>/app</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>volumes:</span></span>
<span class="line"><span>  - /work/storage/tradeboard/db:/app/db</span></span>
<span class="line"><span>  - /work/storage/tradeboard/log:/app/log</span></span>
<span class="line"><span>  - /work/storage/tradeboard/keys:/app/keys</span></span>
<span class="line"><span>  - /work/storage/tradeboard/strategies:/app/strategies</span></span>
<span class="line"><span>  - /work/storage/tradeboard/tmp:/app/tmp</span></span>
<span class="line"><span>  - /work/storage/tradeboard/.env:/app/.env</span></span></code></pre></div><p>Mounting to <code>/tradeboard/...</code> writes to a directory the application never reads, so nothing persists. The shipped <code>docker-compose.yaml</code> uses named volumes for these same five paths; replace them with bind mounts only if you want the files visible on the host filesystem.</p></li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The container runs as UID/GID 1000. Give the host directories and the <code>.env</code> file that ownership, or the first-run secret rotation cannot write and the worker restarts in a loop:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo chown -R 1000:1000 /work/storage/tradeboard</span></span>
<span class="line"><span>sudo chmod 600 /work/storage/tradeboard/.env</span></span></code></pre></div></div><h3 id="securing-your-setup" tabindex="-1">Securing your setup <a class="header-anchor" href="#securing-your-setup" aria-label="Permalink to &quot;Securing your setup&quot;">​</a></h3><h4 id="a-basic-server-protection-iptables-fail2ban" tabindex="-1">A. Basic Server Protection (iptables, fail2ban) <a class="header-anchor" href="#a-basic-server-protection-iptables-fail2ban" aria-label="Permalink to &quot;A. Basic Server Protection (iptables, fail2ban)&quot;">​</a></h4><p><strong>1. Install iptables</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-get update</span></span>
<span class="line"><span>sudo apt-get install iptables</span></span></code></pre></div><ul><li><p>Example: Allow SSH and HTTP(S), block others:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo iptables -A INPUT -p tcp --dport 22 -j ACCEPT</span></span>
<span class="line"><span>sudo iptables -A INPUT -p tcp --dport 80 -j ACCEPT</span></span>
<span class="line"><span>sudo iptables -A INPUT -p tcp --dport 443 -j ACCEPT</span></span>
<span class="line"><span>sudo iptables -A INPUT -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT</span></span>
<span class="line"><span>sudo iptables -A INPUT -j DROP</span></span>
<span class="line"><span>sudo iptables-save | sudo tee /etc/iptables/rules.v4</span></span></code></pre></div></li><li><p><a href="https://help.ubuntu.com/community/IptablesHowTo" target="_blank" rel="noreferrer">iptables guide</a></p></li></ul><p><strong>2. Install fail2ban</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-get install fail2ban</span></span></code></pre></div><ul><li><p>Enable default jails for SSH, edit <code>/etc/fail2ban/jail.local</code> for customization.</p></li><li><p>Start and enable service:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl enable fail2ban</span></span>
<span class="line"><span>sudo systemctl start fail2ban</span></span></code></pre></div></li><li><p><a href="https://www.fail2ban.org/wiki/index.php/Main_Page" target="_blank" rel="noreferrer">fail2ban documentation</a></p></li><li><p><a href="https://linuxize.com/post/how-to-install-fail2ban-on-ubuntu-20-04/" target="_blank" rel="noreferrer">Example setup</a></p></li></ul><h4 id="b-using-cloudflare-for-reverse-proxy-security" tabindex="-1">B. Using Cloudflare for Reverse Proxy &amp; Security <a class="header-anchor" href="#b-using-cloudflare-for-reverse-proxy-security" aria-label="Permalink to &quot;B. Using Cloudflare for Reverse Proxy &amp; Security&quot;">​</a></h4><ul><li><strong>Register at</strong> <a href="https://www.cloudflare.com/" target="_blank" rel="noreferrer"><strong>Cloudflare</strong></a><strong>.</strong></li><li><strong>Add Your Domain:</strong><ul><li>Point your domain&#39;s DNS to Cloudflare&#39;s nameservers.</li><li>Set up <a href="https://developers.cloudflare.com/dns/add-domain/" target="_blank" rel="noreferrer">proxy status</a> for your domain so Cloudflare sits between users and your Pi.</li></ul></li><li><strong>HTTPS and SSL:</strong><ul><li>Use Cloudflare’s “Flexible SSL” or, for end-to-end encryption, generate origin certificates on Cloudflare and install them behind Nginx.</li></ul></li><li><strong>Firewall Rules &amp; Monitoring:</strong><ul><li>Enable Cloudflare Web Application Firewall (WAF).</li><li>Set up custom routes, rate limiting, and security rules.</li><li><a href="https://developers.cloudflare.com/waf/" target="_blank" rel="noreferrer">Cloudflare dashboard security settings</a></li></ul></li><li><strong>Analytics &amp; DDoS Protection:</strong><ul><li>Monitor connection health and traffic patterns through Cloudflare Analytics.</li></ul></li><li><a href="https://developers.cloudflare.com/ssl/origin-configuration/ssl/nginx/" target="_blank" rel="noreferrer">Cloudflare Nginx integration guide</a></li></ul><hr><h3 id="useful-references" tabindex="-1">Useful References <a class="header-anchor" href="#useful-references" aria-label="Permalink to &quot;Useful References&quot;">​</a></h3><ul><li><a href="https://github.com/wesoftcorp/tradeboard" target="_blank" rel="noreferrer">Tradeboard GitHub</a></li><li><a href="https://docs.algo.wesoftcorp.com" target="_blank" rel="noreferrer">Tradeboard Documentation</a></li><li><a href="https://docs.docker.com/engine/install/ubuntu/" target="_blank" rel="noreferrer">Docker Install Ubuntu</a></li><li><a href="https://github.com/wesoftcorp/tradeboard/blob/main/install/install-multi.sh" target="_blank" rel="noreferrer">Nginx Reverse Proxy Setup</a></li><li><a href="https://github.com/wesoftcorp/tradeboard/blob/main/docker-compose.yaml" target="_blank" rel="noreferrer">Persistent Volumes Example</a></li><li><a href="https://help.ubuntu.com/community/IptablesHowTo" target="_blank" rel="noreferrer">IPTables Guide</a></li><li><a href="https://www.fail2ban.org/wiki/index.php/Main_Page" target="_blank" rel="noreferrer">fail2ban documentation</a></li><li><a href="https://developers.cloudflare.com/waf/" target="_blank" rel="noreferrer">Cloudflare dashboard security settings</a></li><li><a href="https://developers.cloudflare.com/ssl/origin-configuration/ssl/nginx/" target="_blank" rel="noreferrer">Cloudflare Nginx integration guide</a></li></ul><p><strong>Tradeboard is now ready on your Raspberry Pi! Start building and deploying your trading strategies.</strong></p>`,54)])])}const m=e(i,[["render",p]]);export{b as __pageData,m as default};
